<?php
namespace App\Http\Controllers\Web; use App\Http\Controllers\Controller; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth;
class AuthController extends Controller { public function create(){return view('auth.login');} public function store(Request $r){$c=$r->validate(['email'=>'required|email','password'=>'required']);if(Auth::attempt($c,true)){if(!in_array(Auth::user()->role,['owner','admin'],true)){Auth::logout();return back()->withErrors(['email'=>'Administrator access required.']);}$r->session()->regenerate();return redirect()->intended('/admin/tracking-settings');}return back()->withErrors(['email'=>'Invalid credentials.'])->onlyInput('email');} public function destroy(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect('/login');} }
